{"code":"func slots(s: String, marker: String): Int64 {
    if (marker.isEmpty()) {
        return Int64(s.toRuneArray().size) + 1
    }
    var count: Int64 = 0
    var start: Int64 = 0
    let n = s.size
    let m = marker.size
    while (start + m <= n) {
        if (s[start..start + m] == marker) {
            count++
            start += m
        } else {
            start++
        }
    }
    return count
}

main() {
    println(slots("中文", "") == 3)
    println(slots("🙂a", "") == 3)
}
"}

