{"code":"func tagDepth(s: String, tag: String): Int64 {
    if (tag.isEmpty()) {
        return 0
    }
    var count: Int64 = 0
    var cur = s
    while (cur.endsWith(tag)) {
        count++
        cur = cur[0..(cur.size - tag.size)]
    }
    return count
}

main() {
    println(tagDepth("a.tmp.tmp", ".tmp") == 2)
    println(tagDepth("哈哈哈", "哈") == 3)
}
"}

