{"code":"func longestRun(words: Array<String>): Int64 {
    var best: Int64 = 0
    var count: Int64 = 0
    var prev: String = ""
    var first: Bool = true
    for (word in words) {
        let cur = word.toAsciiLower()
        if (!first && cur == prev) {
            count += 1
        } else {
            count = 1
        }
        prev = cur
        first = false
        if (count > best) {
            best = count
        }
    }
    best
}

main() {
    println(longestRun(["a", "A", "a", "b"]) == 3)
    println(longestRun(["X", "x"]) == 2)
}
"}

