{"code":"func frameColumns(s: String, n: Int64): String {
    if (n == 0) {
        return ""
    }
    var out = ""
    var count: Int64 = 0
    var start: Int64 = 0
    let size = s.size
    var i: Int64 = 0
    while (i < size && count < n - 1) {
        if (s[i] == r'|') {
            out += "[" + s[start..i] + "]"
            count += 1
            start = i + 1
        }
        i += 1
    }
    out += "[" + s[start..] + "]"
    return out
}

main() {
    println(frameColumns("a||b", 2) == "[a][|b]")
    println(frameColumns("|x", 1) == "[|x]")
}
"}

