func lastReading(words: Array<String>, fallback: Int64): Int64 {
    var answer = fallback
    for (word in words) {
        try {
            let value = Int64.parse(word.trimAscii())
            if (value >= -999 && value <= 999) {
                answer = value
            }
        } catch (_: Exception) {
        }
    }
    answer
}

main() {
    println(lastReading(["2", "bad", " 9 "], 0) == 9)
    println(lastReading(["1", "-4"], 7) == -4)
}
"}

