{"code":"func agreeVotes(words: Array<String>, key: String): Int64 {
    var n: Int64 = 0
    for (w in words) {
        if (asciiEqualsIgnoreCase(w, key)) {
            n += 1
        }
    }
    return n
}

func asciiEqualsIgnoreCase(a: String, b: String): Bool {
    let ra = a.toRuneArray()
    let rb = b.toRuneArray()
    if (ra.size != rb.size) {
        return false
    }
    var i: Int64 = 0
    while (i < ra.size) {
        if (asciiLower(ra[i]) != asciiLower(rb[i])) {
            return false
        }
        i += 1
    }
    return true
}

func asciiLower(r: Rune): Rune {
    if (r >= r'A' && r <= r'Z') {
        return Rune(Int64(r) + 32)
    }
    return r
}

main() {
    println(agreeVotes(["Yes", " YES", "yes"], "YES") == 2)
    println(agreeVotes(["Aa", "aA"], "aa") == 2)
}
"}

