{"code":"func dropEnds(a: Array<Int64>, n: Int64): Array<Int64> {
    if (2 * n >= a.size) {
        return Array<Int64>()
    }
    return a.clone(n..(a.size - n))
}

main() {
    let x0 = [1, 2, 3, 4]
    let y0 = dropEnds(x0, 1)
    let ok0 = y0 == [2, 3]
    if (y0.size > 0) {
        y0[0] = 12345
    }
    println(ok0 && x0 == [1, 2, 3, 4])
    let x1 = [5]
    let y1 = dropEnds(x1, 0)
    let ok1 = y1 == [5]
    if (y1.size > 0) {
        y1[0] = 12345
    }
    println(ok1 && x1 == [5])
}
"}

